import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/ai_provider.dart';
class AiChatScreen extends StatefulWidget{const AiChatScreen({super.key});@override State<AiChatScreen> createState()=>_AiChatScreenState();}
class _AiChatScreenState extends State<AiChatScreen>{final c=TextEditingController();Future<void> send()async{final q=c.text.trim();if(q.isEmpty)return;c.clear();try{await context.read<AiProvider>().send(q);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context){final ai=context.watch<AiProvider>();return Scaffold(appBar:AppBar(title:const Text('CineVerse AI')),body:Column(children:[Expanded(child:ListView.builder(reverse:false,itemCount:ai.messages.length,itemBuilder:(_,i){final m=ai.messages[i];return Align(alignment:m.isUser?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.all(8),padding:const EdgeInsets.all(12),constraints:const BoxConstraints(maxWidth:340),decoration:BoxDecoration(color:m.isUser?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(16)),child:Text(m.text)));})),if(ai.loading)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:c,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'اكتب سؤالك...'))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]));}}
